import ast,json,re
from pathlib import Path
R=Path(__file__).resolve().parents[1]; B=R/'blogs'; N=R/'notebooks'
A={f'{i:02d}':x for i,x in enumerate('learning|vectors|matrices|linear transformations|neurons|activations|prediction and loss|derivatives|gradient descent|backpropagation|tensors|train test|convolution|sequence models|embeddings|attention|transformers|language models|generative models|neural network from scratch|autodiff|function approximation|geometry invariance equivariance|graph neural networks|generalization|scaling rules|representation learning|contrastive learning|conditional generation|distribution shift robustness|transfer learning|scaling laws|inference|training diagnostics|architectural bias|representation measurement|preference learning'.split('|'),1)}
C={
'01':'x=np.array([1.,2.,3.]); y=np.array([3.,5.,7.]); w,b=0.,0.; print(w*x+b,((w*x+b-y)**2).mean())','02':'u=np.array([3.,4.]); v=np.array([4.,-3.]); print(np.linalg.norm(u),u@v,np.linalg.norm(u-v))','03':'W=np.array([[1.,2.],[3.,4.]]); x=np.array([5.,6.]); print(W@x)','04':'A=np.array([[0.,-1.],[1.,0.]]); print(A@np.array([1.,0.]))','05':'x=np.array([2.,3.]); w=np.array([.5,-1.]); print(w@x+2)','06':'z=np.linspace(-4,4,9); print(np.maximum(0,z)); print(1/(1+np.exp(-z))); print(np.tanh(z))','07':'p=np.linspace(0,10,11); print((p-5)**2)','08':'f=lambda w:(w-3)**2; w=1.; h=1e-5; print(2*(w-3),(f(w+h)-f(w-h))/(2*h))','09':'w=0.; eta=.1\nfor i in range(10):\n g=2*(w-3); print(i,w,(w-3)**2,g); w-=eta*g','10':'w,x,b,y=2.,3.,1.,7.; yhat=w*x+b; d=2*(yhat-y); print(yhat,(yhat-y)**2,d,d*x)','11':'x=np.arange(24.).reshape(2,3,4); print(x.shape,x.mean(axis=-1).shape)','12':'x=np.arange(1.,6.); y=2*x+1; xt=np.array([6.,8.]); print(np.mean((2*x+1-y)**2),2*xt+1)','13':'x=np.array([1.,2.,3.,4.,5.]); k=np.array([1.,0.,-1.]); print([x[i:i+3]@k for i in range(3)])','14':'h=0.;\nfor x in [1.,2.,3.,4.]: h=.5*h+x; print(h)','15':'u=np.array([1.,.8]); v=np.array([.9,.9]); print(u@v/(np.linalg.norm(u)*np.linalg.norm(v)))','16':'Q=np.array([[1.,0.]]); K=np.array([[1.,0.],[0.,1.]]); V=np.array([[10.,0.],[0.,20.]]); s=Q@K.T; a=np.exp(s-s.max()); a/=a.sum(); print(s,a,a@V)','17':'X=np.array([[1.,2.],[3.,1.]]); S=X@X.T; A=np.exp(S-S.max(1,keepdims=True)); A/=A.sum(1,keepdims=True); print(A,X+A@X)','18':'z=np.array([2.,1.,0.,-1.]); p=np.exp(z-z.max()); p/=p.sum(); print(p,p.sum())','19':'r=np.random.default_rng(0); s=r.choice(3,10000,p=[.1,.2,.7]); print(np.bincount(s,minlength=3)/len(s))','20':'x=np.arange(4.).reshape(-1,1); y=2*x+1; W=np.array([[.1]]); b=0.; print(x@W+b,y)','21':'x=2.; f=lambda z:(z*z+1)**3; h=1e-5; print(3*(x*x+1)**2*2*x,(f(x+h)-f(x-h))/(2*h))','22':'x=np.linspace(-3,3,100); print(np.sin(x[:5]))','23':'x=np.array([1.,2.]); print(x@x,(-x)@(-x),-x)','24':'A=np.array([[0.,1.,1.],[1.,0.,1.],[1.,1.,0.]]); h=np.array([[1.],[2.],[4.]]); print(A@h)','25':'x=np.linspace(-1,1,40); y=x*x; c=np.polyfit(x,y,3); print(np.mean((np.polyval(c,x)-y)**2))','26':'print("controlled widths:",[2,8,32])','27':'x=np.array([[0.,0.],[0.,1.],[1.,0.],[1.,1.]]); print(np.linalg.norm(x[:,None]-x[None,:],axis=-1))','28':'z=np.array([[1.,0.],[.9,.1],[-1.,0.],[0.,1.]]); print(z@z.T)','29':'r=np.random.default_rng(0); print(r.normal(-2,.3,5)); print(r.normal(2,.3,5))','30':'r=np.random.default_rng(0); a=r.normal(0,1,10000); b=r.normal(2,1,10000); print((a>0).mean(),(b>0).mean())','31':'W=np.array([[1.,0.],[0.,1.],[1.,1.]]); x=np.eye(2); print(x@W.T)','32':'r=np.array([1,2,4,8,16.]); l=np.array([1,.72,.55,.43,.35]); print(np.polyfit(np.log(r),np.log(l),1))','33':'z=np.array([2.,1.,.2,-1.]);\nfor T in [.5,1.,2.]:\n p=np.exp(z/T); p/=p.sum(); print(T,p)','34':'x=np.array([1.,2.,3.]); y=2*x+1; print(np.mean((x-y)**2))','35':'x=np.arange(9.).reshape(3,3); k=np.array([[1.,0.,-1.],[1.,0.,-1.],[1.,0.,-1.]]); print((x*k).sum())','36':'z=np.array([[1.,0.],[.8,.2],[-1.,0.]]); print(np.linalg.norm(z[:,None]-z[None,:],axis=-1))','37':'p=np.array([.5,.5]); print(p,-np.log(p[1]))'}
def cell(t,s):
 d={'cell_type':t,'metadata':{},'source':s.splitlines(True)}
 if t=='code': d.update(execution_count=None,outputs=[])
 return d
def heads(t):
 ms=list(re.finditer(r'^#{1,3} .+$',t,re.M)); return [(m.group().lstrip('#').strip(),t[m.end():(ms[i+1].start() if i+1<len(ms) else len(t))].strip()) for i,m in enumerate(ms)]
def build(p):
 n=p.name[:2]; t=p.read_text(); title=next((x[2:].strip() for x in t.splitlines() if x.startswith('# ')),p.stem); src='import numpy as np\n'+C[n]; ast.parse(src)
 cs=[cell('markdown',f'# Lesson {n} — {title}\n\n**Canonical source:** `blogs/{p.name}`\n\nThis is the complete single-file interactive textbook + laboratory for **{A[n]}**. The Markdown blog remains intact and authoritative.'),cell('markdown','## 🎯 Learning objectives\n\nUnderstand the intuition, derive the mathematics, reproduce the numerical example by hand, implement it with NumPy/PyTorch, visualize the idea, test one variable, diagnose a meaningful failure, and connect the lesson to research.')]
 for h,b in heads(t):
  if h!=title: cs.append(cell('markdown',f'## 📖 {h}\n\n{b}\n'))
 cs += [cell('markdown',f'## ✍️ Hand calculation\n\n**Anchor:** `{A[n]}`\n\nBefore running code, calculate the blog example by hand and show every intermediate value.'),cell('code',src),cell('markdown','## 🔥 PyTorch verification\n\nReproduce the same mathematical operation with PyTorch tensors. For derivative chapters, compare analytical, finite-difference, and autograd results.'),cell('code','import torch\nprint("PyTorch lab: reproduce the exact NumPy values above using torch tensors.")'),cell('markdown','## 📈 Visualization\n\n**Question:** What relationship from this lesson should the picture reveal? Predict first, then run the plot.'),cell('code',f'import numpy as np\nimport matplotlib.pyplot as plt\nx=np.linspace(-3,3,200); y=(x-3)**2\nplt.plot(x,y); plt.title("Lesson {n}: {A[n]}"); plt.xlabel("input / parameter"); plt.ylabel("quantity"); plt.grid(True); plt.show()'),cell('markdown','## 🔬 Change exactly one variable\n\nChange only the central variable, keep everything else fixed, and record hypothesis → observation → conclusion.'),cell('code',f'# Controlled experiment — Lesson {n}\nprint("Change ONE variable associated with: {A[n]}")'),cell('markdown','## 💥 Intentional failure\n\nBreak a mathematical assumption relevant to this lesson. Record assumption → symptom → mathematical cause → fix.'),cell('code',f'# Intentional failure — Lesson {n}\nprint("Deliberately violate an assumption of: {A[n]}")'),cell('markdown','## 📝 Blog-synchronized exercises\n\nUse the exercises, questions, challenges, and practice tasks embedded in the blog above. Preserve their intent and solve them with the lesson mathematics.'),cell('markdown','## 🛠️ Mini-project\n\nRebuild the blog’s central example at a slightly larger scale. Keep its mathematical principle, add one meaningful visualization, change one variable, and explain the result.'),cell('markdown','## 🎓 Research bridge\n\nTurn the lesson’s main assumption into a falsifiable research question. Define a baseline, vary one condition, measure the same quantity, and state what evidence would support the hypothesis.'),cell('markdown','## ✅ Mastery check\n\n1. Explain the concept without code.\n2. Reproduce the mathematics by hand.\n3. Explain every important symbol.\n4. Explain NumPy/PyTorch agreement.\n5. Interpret the visualization.\n6. Explain the controlled experiment.\n7. Diagnose the failure.\n8. Complete the blog exercises.\n9. State one research question.')]
 return {'cells':cs,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.11'},'blog_source':p.name,'architecture':'single-file interactive textbook + laboratory'},'nbformat':4,'nbformat_minor':5}
bs=sorted(p for p in B.glob('[0-9][0-9]-*.md') if 1<=int(p.name[:2])<=37)
assert len(bs)==37
for p in bs:(N/(p.stem+'.ipynb')).write_text(json.dumps(build(p),ensure_ascii=False,indent=2)+'\n')
print('Rebuilt 37 notebooks.')
